    "本期增量两条：①贵州轮胎摩洛哥全资二级子公司ADVANCE TYRE MOROCCO SAS完成注册登记（10-19登记，注册资本99,000迪拉姆）——公司第二海外生产基地主体落地，与森麒麟同选址丹吉尔科技城，轮胎业摩洛哥赛道跟随者再添一家；②腾讯GMTN计划完成发行18亿美元＋人民币260亿元四系列优先票据（10-21纽约时间完成；人民币200亿2.40%/2036、60亿3.00%/2056，美元13亿6.10%/2036、5亿6.75%/2046）——并入10-12建议发行原条目，事件链由意向推进至完成。巨潮另3条命中中2条（晶科财务资助、兖矿澳洲Q3产销量）前批已收录去重，奥士康制度文件与中材国际银行间发债误匹配剔除。",
