    "本窗口主线为A股公司H股上市潮的集中兑现：9月29日单日三家挂牌——罗博特科（436.00港元/股，净筹约49.61亿港元）、景旺电子（69.88港元/股，净筹约49.61亿港元）、彤程新材（44.00港元/股，净筹约29亿港元），星环科技9月21日挂牌（净筹约6.3亿港元）并同日调入港股通；传音控股、军信股份刊发聆讯后资料集（审核端推进），翱捷科技递交申请（增量端）；反向信号：博瑞医药H股申报到期主动终止。产业端实质动作集中在产能与贸易救济：联科科技拟投约10亿元在埃及苏伊士运河经济特区建二氧化硅-炭黑一体化基地（新加坡-埃及三层架构）；中富电路增资泰国PCB基地不超5亿元（WTT尚处亏损爬坡期）；华海药业阿哌沙班片获德国上市许可（研发投入仅约369万元，对标52.7亿美元欧洲市场）；中源家居美国子公司收到CBP退回IEEPA关税及利息约169.5万美元（占净利润绝对值40.49%）；酷特智能终止收购韩国apM集团股权（止于MOU阶段）。港股渠道收录联想集团6.75亿美元可转债悉数转换注销、美元债工具清零收官。"
