      "before": "现金＋设备资产出资合计约1.6亿澳元（约7.66亿元人民币），其中现金约2,000万澳元、机器设备作价约1.4亿澳元",
      "after": "拟取得项目公司约80%权益（现金＋机器设备作价出资，金额未定）",
