      "field": "风险表述",
      "before": "FIRB（澳外资审查）审批为关键先决条件；关联交易定价公允性；尽调与估值未落定；钛锆价格周期；澳元汇率；最终交易结构（股权收购vs非法人合资UJV）未定；9月2",
      "after": "最终交易文件能否按期签署（已延长一次）；尽调与估值分歧；澳方外资审查；矿业开发周期",
